python3 -I -c "import pathlib,json,hashlib,datetime,subprocess; d=json.loads(pathlib.Path('audit/session-recovery-0147.json').read_text());
def resolve(pointer):
 path,fragment=pointer.split('#',1); value=json.loads(pathlib.Path(path).read_text());
 for key in fragment.strip('/').split('/'):
  value=value[int(key)] if isinstance(value,list) else value[key]
 return value
for source,meta in d['sources'].items():
 raw=subprocess.check_output(['git','show',source]) if ':sessions/' in source else pathlib.Path(source).read_bytes(); assert hashlib.sha256(raw).hexdigest()==meta['sha256']
for n,s in d['sessions'].items():
 for m in s['durations']:
  a=datetime.datetime.fromisoformat(m['start'].replace('Z','+00:00')); b=datetime.datetime.fromisoformat(m['end'].replace('Z','+00:00')); assert (b-a).total_seconds()==m['seconds'];
  if len(m['evidence'])==2 and all('#/' in p and p.startswith('.session/exports/actions/') for p in m['evidence']): assert [resolve(p) for p in m['evidence']]==[m['start'],m['end']]
 for event in s['timeline']:
  if event['source'].startswith('.session/exports/actions/'):
   original=resolve(event['source']); assert original['name']==event['name'] and original['conclusion']==event['conclusion']; assert original.get('started_at')==event.get('start') and original.get('completed_at')==event.get('end')
 epilogues=[e for e in s['timeline'] if e['kind']=='step' and e['name']=='Epilogue']; assert [e['conclusion'] for e in epilogues]==(['success'] if n=='669' else ['failure','success']);
 for e in s['timeline']:
  if e['kind']=='step' and e['name']!='Epilogue': assert e['conclusion']=='success'
 for key in ['first_saved_at','last_saved_at']:
  assert any(e['start']<=s['runtime'][key]<=e['end'] for e in epilogues)
 print(n,'checked',len(s['durations']),'durations;',len(s['timeline']),'timeline entries; artifacts',s['saved_record']['artifacts'])
assert [d['sessions'][n]['saved_record']['artifacts'] for n in ['643','653','663','669']]==[0,0,0,12]
assert all(pathlib.Path(p).stat().st_size<2000000 for p in ['audit/0147.md','audit/latest.md','audit/session-recovery-0147.json','audit/metrics/session_recovery_0147.py'])
print('Verified',len(d['sources']),'source hashes; source pointers, phase outcomes, timestamp pairs, checkpoint placement and size limits.'); print(pathlib.Path('audit/0147.md').read_text()); print(subprocess.check_output(['git','diff','--check'],text=True)); print(subprocess.check_output(['git','status','--short'],text=True))"

